// Filtra solo filas con número WhatsApp válido
const items = $input.all();
return items.filter(item => {
  const wa = item.json.WhatsApp || '';
  return wa.startsWith('+54') || wa.startsWith('54');
});

// Arma el número limpio y la URL de wa.me con el mensaje pre-cargado
const item = $input.item.json;

// Limpiar número: quitar +, espacios, guiones
const rawNum = (item.WhatsApp || '').replace(/[^\d]/g, '');

// Nombre del local para personalizar
const nombre = item.Nombre || '';

// Tipo para elegir plantilla
const tipo = (item.Tipo || '').toLowerCase();

// Elegir plantilla según tipo
let mensaje;
if (tipo.includes('italian') || tipo.includes('trattoria') || tipo.includes('autor') || tipo.includes('bistro')) {
  mensaje = `Hola ${nombre} 👋 Les escribo de Eurocrem, somos productores de helado de la zona. Vi que tienen una carta que cuida mucho el postre y por eso me animo: trabajamos un helado de calidad para restaurantes, con pocos sabores bien logrados, pensado para cerrar la experiencia de una buena mesa. ¿Les interesaría que les acerque una muestra para que lo prueben sin compromiso?`;
} else if (tipo.includes('parrilla') || tipo.includes('bodeg')) {
  mensaje = `Hola ${nombre}, ¿cómo andan? Les escribo de Eurocrem, hacemos helado para restaurantes acá en la zona. Sabemos que en una parrilla el postre tiene que salir rápido, rendir y gustar a todos. Tenemos un helado pensado justo para eso, a buen precio por volumen y con entrega propia. ¿Puedo pasar a dejarles una muestra para que la prueben?`;
} else {
  mensaje = `Hola ${nombre} 👋 Les escribo de Eurocrem, somos una fábrica de helado de la zona y trabajamos con restaurantes para la parte de postres. Calidad media-alta, pocos sabores bien hechos, entrega propia. ¿Les interesaría recibir una muestra sin compromiso para evaluarla?`;
}

// Construir URL wa.me con texto codificado
const mensajeCodificado = encodeURIComponent(mensaje);
const waUrl = `https://wa.me/${rawNum}?text=${mensajeCodificado}`;

return {
  ...item,
  numero_limpio: rawNum,
  mensaje_preparado: mensaje,
  wa_url: waUrl
};
